-- ====================================================================
-- MealBridge AI Database Backup (Restored SQL)
-- Source: MealBridge_food_donation.backup (PostgreSQL custom format 1.16)
-- Database: food_donation_db
-- ====================================================================

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;

CREATE SEQUENCE public.assignments_assignment_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.audit_logs_audit_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.delivery_confirmations_confirmation_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.delivery_tracking_tracking_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.donations_donation_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.kb_chunks_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.matches_match_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.messages_message_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.ngos_ngo_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.notifications_notification_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.users_user_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE SEQUENCE public.volunteers_volunteer_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


CREATE TABLE public.assignments (
    assignment_id integer NOT NULL,
    donation_id integer NOT NULL,
    ngo_id integer NOT NULL,
    volunteer_id integer,
    pickup_location character varying(255),
    delivery_location character varying(255),
    pickup_time timestamp without time zone,
    delivery_time timestamp without time zone,
    status character varying(30) DEFAULT 'ASSIGNED'::character varying,
    assigned_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE public.audit_logs (
    audit_id integer NOT NULL,
    user_id integer NOT NULL,
    action character varying(100) NOT NULL,
    entity_type character varying(50),
    entity_id integer,
    details text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE public.delivery_confirmations (
    confirmation_id integer NOT NULL,
    donation_id integer NOT NULL,
    ngo_id integer NOT NULL,
    volunteer_id integer NOT NULL,
    confirmed_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    verification_method character varying(50),
    remarks text
);


CREATE TABLE public.delivery_tracking (
    tracking_id integer NOT NULL,
    assignment_id integer NOT NULL,
    volunteer_id integer NOT NULL,
    latitude numeric(10,7) NOT NULL,
    longitude numeric(10,7) NOT NULL,
    accuracy numeric(10,2),
    speed numeric(10,2),
    heading numeric(10,2),
    status character varying(30) NOT NULL,
    recorded_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE public.donations (
    donation_id integer NOT NULL,
    donor_id integer NOT NULL,
    food_name character varying(100) NOT NULL,
    food_type character varying(50),
    quantity numeric(10,2) NOT NULL,
    unit character varying(20),
    expiry_time timestamp without time zone NOT NULL,
    pickup_start timestamp without time zone,
    pickup_end timestamp without time zone,
    location character varying(255),
    latitude numeric(10,7),
    longitude numeric(10,7),
    image_url character varying(255),
    status character varying(30) DEFAULT 'POSTED'::character varying,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    embedding public.vector(384)
);


CREATE TABLE public.kb_chunks (
    id integer NOT NULL,
    source character varying(255) NOT NULL,
    text text NOT NULL,
    embedding public.vector(384)
);


CREATE TABLE public.matches (
    match_id integer NOT NULL,
    donation_id integer NOT NULL,
    ngo_id integer NOT NULL,
    location_score numeric(5,2),
    quantity_score numeric(5,2),
    expiry_score numeric(5,2),
    capacity_score numeric(5,2),
    requirement_score numeric(5,2),
    total_score numeric(5,2),
    status character varying(30) DEFAULT 'PENDING'::character varying,
    matched_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    similarity_score numeric
);


CREATE TABLE public.messages (
    message_id integer NOT NULL,
    assignment_id integer NOT NULL,
    sender_id integer NOT NULL,
    message text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


CREATE TABLE public.ngos (
    ngo_id integer NOT NULL,
    user_id integer NOT NULL,
    organization_name character varying(150) NOT NULL,
    email character varying(150),
    email_verified boolean DEFAULT false NOT NULL,
    email_verified_at timestamp without time zone,
    address text,
    capacity numeric(10,2),
    capacity_unit character varying(20),
    food_requirements text,
    latitude numeric(10,7),
    longitude numeric(10,7),
    verification_status character varying(30) DEFAULT 'PENDING'::character varying,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    embedding public.vector(384)
);


CREATE TABLE public.ngo_email_verification_tokens (
    id SERIAL PRIMARY KEY,
    ngo_id integer NOT NULL REFERENCES public.ngos(ngo_id) ON DELETE CASCADE,
    token character varying(255) NOT NULL,
    expires_at timestamp without time zone NOT NULL,
    used_at timestamp without time zone,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


CREATE TABLE public.notifications (
    notification_id integer NOT NULL,
    user_id integer NOT NULL,
    message text NOT NULL,
    notification_type character varying(50),
    is_read boolean DEFAULT false,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE public.users (
    user_id integer NOT NULL,
    name character varying(100) NOT NULL,
    email character varying(150) NOT NULL,
    password character varying(255) NOT NULL,
    phone character varying(15),
    role character varying(20) NOT NULL,
    location character varying(255),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE public.volunteers (
    volunteer_id integer NOT NULL,
    user_id integer NOT NULL,
    availability character varying(30),
    vehicle_type character varying(50),
    vehicle_number character varying(30),
    current_location character varying(255),
    latitude numeric(10,7),
    longitude numeric(10,7),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE ONLY public.assignments ALTER COLUMN assignment_id SET DEFAULT nextval('public.assignments_assignment_id_seq'::regclass);


ALTER TABLE ONLY public.audit_logs ALTER COLUMN audit_id SET DEFAULT nextval('public.audit_logs_audit_id_seq'::regclass);


ALTER TABLE ONLY public.delivery_confirmations ALTER COLUMN confirmation_id SET DEFAULT nextval('public.delivery_confirmations_confirmation_id_seq'::regclass);


ALTER TABLE ONLY public.delivery_tracking ALTER COLUMN tracking_id SET DEFAULT nextval('public.delivery_tracking_tracking_id_seq'::regclass);


ALTER TABLE ONLY public.donations ALTER COLUMN donation_id SET DEFAULT nextval('public.donations_donation_id_seq'::regclass);


ALTER TABLE ONLY public.kb_chunks ALTER COLUMN id SET DEFAULT nextval('public.kb_chunks_id_seq'::regclass);


ALTER TABLE ONLY public.matches ALTER COLUMN match_id SET DEFAULT nextval('public.matches_match_id_seq'::regclass);


ALTER TABLE ONLY public.messages ALTER COLUMN message_id SET DEFAULT nextval('public.messages_message_id_seq'::regclass);


ALTER TABLE ONLY public.ngos ALTER COLUMN ngo_id SET DEFAULT nextval('public.ngos_ngo_id_seq'::regclass);


ALTER TABLE ONLY public.notifications ALTER COLUMN notification_id SET DEFAULT nextval('public.notifications_notification_id_seq'::regclass);


ALTER TABLE ONLY public.users ALTER COLUMN user_id SET DEFAULT nextval('public.users_user_id_seq'::regclass);


ALTER TABLE ONLY public.volunteers ALTER COLUMN volunteer_id SET DEFAULT nextval('public.volunteers_volunteer_id_seq'::regclass);


