ALTER TABLE ONLY public.assignments
    ADD CONSTRAINT assignments_pkey PRIMARY KEY (assignment_id);


ALTER TABLE ONLY public.audit_logs
    ADD CONSTRAINT audit_logs_pkey PRIMARY KEY (audit_id);


ALTER TABLE ONLY public.delivery_confirmations
    ADD CONSTRAINT delivery_confirmations_pkey PRIMARY KEY (confirmation_id);


ALTER TABLE ONLY public.delivery_tracking
    ADD CONSTRAINT delivery_tracking_pkey PRIMARY KEY (tracking_id);


ALTER TABLE ONLY public.donations
    ADD CONSTRAINT donations_pkey PRIMARY KEY (donation_id);


ALTER TABLE ONLY public.kb_chunks
    ADD CONSTRAINT kb_chunks_pkey PRIMARY KEY (id);


ALTER TABLE ONLY public.matches
    ADD CONSTRAINT matches_pkey PRIMARY KEY (match_id);


ALTER TABLE ONLY public.messages
    ADD CONSTRAINT messages_pkey PRIMARY KEY (message_id);


ALTER TABLE ONLY public.ngos
    ADD CONSTRAINT ngos_pkey PRIMARY KEY (ngo_id);


ALTER TABLE ONLY public.notifications
    ADD CONSTRAINT notifications_pkey PRIMARY KEY (notification_id);


ALTER TABLE ONLY public.users
    ADD CONSTRAINT users_email_key UNIQUE (email);


ALTER TABLE ONLY public.users
    ADD CONSTRAINT users_pkey PRIMARY KEY (user_id);


ALTER TABLE ONLY public.volunteers
    ADD CONSTRAINT volunteers_pkey PRIMARY KEY (volunteer_id);


CREATE INDEX assignments_donation_idx ON public.assignments USING btree (donation_id);


CREATE INDEX assignments_ngo_idx ON public.assignments USING btree (ngo_id);


CREATE INDEX assignments_volunteer_idx ON public.assignments USING btree (volunteer_id);


CREATE INDEX donations_embedding_idx ON public.donations USING hnsw (embedding public.vector_cosine_ops);


CREATE INDEX donations_status_idx ON public.donations USING btree (status);


CREATE INDEX idx_delivery_tracking_assignment_time ON public.delivery_tracking USING btree (assignment_id, recorded_at DESC);


CREATE INDEX idx_delivery_tracking_volunteer_time ON public.delivery_tracking USING btree (volunteer_id, recorded_at DESC);


CREATE INDEX kb_chunks_embedding_idx ON public.kb_chunks USING hnsw (embedding public.vector_cosine_ops);


CREATE INDEX messages_assignment_idx ON public.messages USING btree (assignment_id, created_at);


CREATE INDEX ngos_embedding_idx ON public.ngos USING hnsw (embedding public.vector_cosine_ops);


CREATE INDEX ngos_verification_idx ON public.ngos USING btree (verification_status);


ALTER TABLE ONLY public.assignments
    ADD CONSTRAINT fk_assignment_donation FOREIGN KEY (donation_id) REFERENCES public.donations(donation_id);


ALTER TABLE ONLY public.assignments
    ADD CONSTRAINT fk_assignment_ngo FOREIGN KEY (ngo_id) REFERENCES public.ngos(ngo_id);


ALTER TABLE ONLY public.assignments
    ADD CONSTRAINT fk_assignment_volunteer FOREIGN KEY (volunteer_id) REFERENCES public.volunteers(volunteer_id);


ALTER TABLE ONLY public.audit_logs
    ADD CONSTRAINT fk_audit_user FOREIGN KEY (user_id) REFERENCES public.users(user_id);


ALTER TABLE ONLY public.delivery_confirmations
    ADD CONSTRAINT fk_confirmation_donation FOREIGN KEY (donation_id) REFERENCES public.donations(donation_id);


