    ADD CONSTRAINT fk_confirmation_ngo FOREIGN KEY (ngo_id) REFERENCES public.ngos(ngo_id);


ALTER TABLE ONLY public.delivery_confirmations
    ADD CONSTRAINT fk_confirmation_volunteer FOREIGN KEY (volunteer_id) REFERENCES public.volunteers(volunteer_id);


