    ADD CONSTRAINT fk_match_donation FOREIGN KEY (donation_id) REFERENCES public.donations(donation_id);


ALTER TABLE ONLY public.matches
    ADD CONSTRAINT fk_match_ngo FOREIGN KEY (ngo_id) REFERENCES public.ngos(ngo_id);


